package com.example

import com.example.ExamQuestionHelper.QSpec

internal object ScienceLiveExamChemAtomBank1 {
  private const val T = "පරමාණුක ව්‍යුහය, ආවර්තිතා වගුව, බන්ධන හා ද්‍රාවණ"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String = "පරමාණුක ව්‍යුහය හා රසායනික බන්ධන පිළිබඳ නිවැරදි කරුණකි."
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("පරමාණුවක න්‍යෂ්ටිය තුළ පිහිටන ධන ආරෝපිත උපපරමාණුක අංශුව කුමක්ද?", "ප්‍රෝටෝනය", "ඉලෙක්ට්‍රෝනය", "නියුට්‍රෝනය", "පොසිට්‍රෝනය", "ප්‍රෝටෝන න්‍යෂ්ටියේ පිහිටන ධන ආරෝපිත අංශු වේ."),
    q("ආරෝපණයක් රහිත (උදාසීන) උපපරමාණුක අංශුව කුමක්ද?", "නියුට්‍රෝනය", "ප්‍රෝටෝනය", "ඉලෙක්ට්‍රෝනය", "ඇල්ෆා අංශුව", "නියුට්‍රෝන න්‍යෂ්ටියේ පිහිටන අතර සාපේක්ෂ ස්කන්ධය 1 කි."),
    q("උදාසීන පරමාණුවක ප්‍රෝටෝන සංඛ්‍යාව සැමවිටම සමාන වන්නේ කුමන සංඛ්‍යාවටද?", "ඉලෙක්ට්‍රෝන සංඛ්‍යාවට", "නියුට්‍රෝන සංඛ්‍යාවට", "ස්කන්ධ ක්‍රමාංකයට", "සංයුජතාවට", "ධන හා සෘණ ආරෝපණ සමාන බැවින් පරමාණුව විද්‍යුත් වශයෙන් උදාසීන වේ."),
    q("මූලද්‍රව්‍යයක පරමාණුක ක්‍රමාංකය (Z) මඟින් නිවැරදිව නිරූපණය කරන්නේ කුමක්ද?", "පරමාණුවක න්‍යෂ්ටියේ ඇති ප්‍රෝටෝන සංඛ්‍යාව", "ප්‍රෝටෝන හා නියුට්‍රෝන එකතුව", "පරමාණුවේ ඇති නියුට්‍රෝන සංඛ්‍යාව", "අවසන් කවචයේ ඉලෙක්ට්‍රෝන ගණන", "පරමාණුක ක්‍රමාංකය මූලද්‍රව්‍යයේ අනන්‍යතාව තීරණය කරයි."),
    q("පරමාණුවක ස්කන්ධ ක්‍රමාංකය (A) ලබා ගන්නේ කෙසේද?", "ප්‍රෝටෝන සංඛ්‍යාව + නියුට්‍රෝන සංඛ්‍යාව", "ප්‍රෝටෝන සංඛ්‍යාව + ඉලෙක්ට්‍රෝන සංඛ්‍යාව", "නියුට්‍රෝන සංඛ්‍යාව - ප්‍රෝටෝන සංඛ්‍යාව", "ඉලෙක්ට්‍රෝන සංඛ්‍යාව පමණි", "ඉලෙක්ට්‍රෝන ස්කන්ධය ඉතා කුඩා බැවින් නොසලකා හරී."),
    q("²³₁₁Na පරමාණුවේ ඇති නියුට්‍රෝන සංඛ්‍යාව කීයද?", "12", "11", "23", "34", "නියුට්‍රෝන ගණන = A - Z = 23 - 11 = 12."),
    q("එකම මූලද්‍රව්‍යයේ පරමාණුක ක්‍රමාංකය සමාන නමුත් නියුට්‍රෝන සංඛ්‍යාව වෙනස් පරමාණු හඳුන්වන්නේ කුමන නමින්ද?", "සමස්ථානික (Isotopes)", "සමඅයනික", "බහුරූපී", "සමාවයවික", "සමස්ථානිකවල රසායනික ගුණ සමාන වන අතර භෞතික ස්කන්ධ ගුණ වෙනස් වේ."),
    q("කාබන්-12 (¹²₆C) සහ කාබන්-14 (¹⁴₆C) යන සමස්ථානික දෙකෙහි සමාන වන්නේ කුමක්ද?", "ප්‍රෝටෝන හා ඉලෙක්ට්‍රෝන සංඛ්‍යාව", "නියුට්‍රෝන සංඛ්‍යාව", "ස්කන්ධ ක්‍රමාංකය", "සාපේක්ෂ පරමාණුක ස්කන්ධය", "දෙකෙහිම ප්‍රෝටෝන 6 බැගින් ඇත; නියුට්‍රෝන 6 හා 8 වේ."),
    q("රන් පත්‍ර පරීක්ෂණය මගින් පරමාණුව මධ්‍යයේ කුඩා ධන ආරෝපිත න්‍යෂ්ටියක් ඇති බව සොයා ගත් විද්‍යාඥයා කවුද?", "අර්නස්ට් රදර්ෆර්ඩ්", "ජෝන් ඩෝල්ටන්", "ජේ. ජේ. තොම්සන්", "නීල්ස් බෝර්", "ඇල්ෆා අංශු ප්‍රකිරණ පරීක්ෂණයෙන් න්‍යෂ්ටික ආකෘතිය ඉදිරිපත් විය."),
    q("පළමු ඉලෙක්ට්‍රෝන කවචයේ (K කවචය) රඳවා ගත හැකි උපරිම ඉලෙක්ට්‍රෝන සංඛ්‍යාව කීයද?", "2", "8", "18", "32", "2n² සූත්‍රය අනුව n = 1 විට 2(1)² = 2 කි."),
    q("පරමාණුක ක්‍රමාංකය 17 වූ ක්ලෝරීන් (Cl) පරමාණුවේ ඉලෙක්ට්‍රෝන වින්‍යාසය කුමක්ද?", "2, 8, 7", "2, 8, 8", "2, 7, 8", "2, 8, 1", "K=2, L=8, M=7 ලෙස ඉලෙක්ට්‍රෝන සකස් වේ."),
    q("පොටෑසියම් (Z = 19) පරමාණුවේ නිවැරදි ඉලෙක්ට්‍රෝන වින්‍යාසය කුමක්ද?", "2, 8, 8, 1", "2, 8, 9", "2, 9, 8", "2, 8, 7, 2", "තෙවන කවචයේ ඉලෙක්ට්‍රෝන 8 ක් පිරුණු පසු ඊළඟ ඉලෙක්ට්‍රෝනය සිව්වන කවචයට යයි."),
    q("නවීන ආවර්තිතා වගුවේ මූලද්‍රව්‍ය පෙළගස්වා ඇත්තේ කුමන අගය ආරෝහණ වන පිළිවෙළටද?", "පරමාණුක ක්‍රමාංකය (Z)", "පරමාණුක ස්කන්ධය", "ඝනත්වය", "ද්‍රවාංකය", "හෙන්රි මෝස්ලි විසින් පරමාණුක ක්‍රමාංකය පදනම් කරගත් ආවර්තිතා නියමය ඉදිරිපත් කරන ලදී."),
    q("ආවර්තිතා වගුවේ යම් මූලද්‍රව්‍යයක් අයත් 'ආවර්ත අංකය' (Period) තීරණය වන්නේ කුමක් මතද?", "ඉලෙක්ට්‍රෝන පිරී ඇති කවච සංඛ්‍යාව මත", "අවසන් කවචයේ ඉලෙක්ට්‍රෝන ගණන මත", "නියුට්‍රෝන ගණන මත", "විද්‍යුත් සෘණතාව මත", "උදා: Na (2, 8, 1) කවච 3 ක් ඇති බැවින් 3 වන ආවර්තයට අයත් වේ."),
    q("ආවර්තිතා වගුවේ I සිට VII දක්වා කාණ්ඩ අංකයෙන් දැක්වෙන්නේ කුමක්ද?", "සංයුජතා කවචයේ (අවසන් කවචයේ) ඉලෙක්ට්‍රෝන ගණන", "මුළු කවච ගණන", "ප්‍රෝටෝන ගණන", "නියුට්‍රෝන ගණන", "උදා: Mg (2, 8, 2) අවසන් කවචයේ ඉලෙක්ට්‍රෝන 2 ක් ඇති බැවින් II කාණ්ඩයට අයත් වේ."),
    q("ඉලෙක්ට්‍රෝන වින්‍යාසය 2, 8, 2 වන මූලද්‍රව්‍යය ආවර්තිතා වගුවේ පිහිටන ස්ථානය කුමක්ද?", "3 වන ආවර්තය, II කාණ්ඩය", "2 වන ආවර්තය, III කාණ්ඩය", "3 වන ආවර්තය, VIII කාණ්ඩය", "4 වන ආවර්තය, II කාණ්ඩය", "කවච 3 ක් හා සංයුජතා ඉලෙක්ට්‍රෝන 2 ක් ඇත (මැග්නීසියම්)."),
    q("ආවර්තිතා වගුවේ I කාණ්ඩයේ මූලද්‍රව්‍ය (Li, Na, K) හඳුන්වන පොදු නාමය කුමක්ද?", "ක්ෂාර ලෝහ (Alkali metals)", "හැලජන", "උච්ච වායු", "ක්ෂාරීය පාංශු ලෝහ", "මේවා ජලය සමඟ තදින් ප්‍රතික්‍රියා කර භාෂ්මික ද්‍රාවණ සාදයි."),
    q("ආවර්තිතා වගුවේ VII කාණ්ඩයේ (F, Cl, Br, I) මූලද්‍රව්‍ය හඳුන්වන්නේ කෙසේද?", "හැලජන (Halogens)", "ක්ෂාර ලෝහ", "උච්ච වායු", "සංක්‍රාන්ති මූලද්‍රව්‍ය", "ලෝහ සමඟ ප්‍රතික්‍රියා කර ලවණ සාදන බැවින් 'හැලජන' නම් වේ."),
    q("සාමාන්‍ය තත්ත්ව යටතේ රසායනික ප්‍රතික්‍රියාවලට සහභාගී නොවන නිෂ්ක්‍රීය වායු අයත් වන්නේ කුමන කාණ්ඩයටද?", "VIII (හෝ 0) කාණ්ඩය", "I කාණ්ඩය", "IV කාණ්ඩය", "VII කාණ්ඩය", "හීලියම්, නියොන් සහ ආගන් අවසන් කවචය සම්පූර්ණ බැවින් ස්ථායී වේ."),
    q("හීලියම් (He) පරමාණුවේ පරමාණුක ක්‍රමාංකය 2 වුවද එය VIII (උච්ච වායු) කාණ්ඩයේ තබා ඇත්තේ ඇයි?", "පළමු කවචය ඉලෙක්ට්‍රෝන 2 කින් සම්පූර්ණ වී ස්ථායී වීම නිසා", "එය ඝන ලෝහයක් නිසා", "එහි නියුට්‍රෝන නැති නිසා", "එය ජලයේ දියවන නිසා", "ද්වික වින්‍යාසය නිසා හීලියම් උච්ච වායු ගුණ පෙන්වයි."),
    q("3 වන ආවර්තය දිගේ වමේ සිට දකුණට යන විට (Na සිට Cl දක්වා) මූලද්‍රව්‍යවල සිදුවන විචලනය කුමක්ද?", "ලෝහක ගුණ අඩු වී අලෝහක ගුණ වැඩි වේ", "ලෝහක ගුණ වැඩි වේ", "පරමාණුක අරය විශාල වේ", "විද්‍යුත් සෘණතාව ශුන්‍ය වේ", "න්‍යෂ්ටික ආරෝපණය වැඩි වීම නිසා පරමාණුක අරය ද ක්‍රමයෙන් කුඩා වේ."),
    q("ආවර්තිතා වගුවේ කාණ්ඩයක් දිගේ ඉහළ සිට පහළට යන විට සිදුවන වෙනස කුමක්ද?", "ශක්ති මට්ටම් ගණන වැඩි වී පරමාණුක අරය විශාල වේ", "පරමාණුක අරය කුඩා වේ", "ප්‍රෝටෝන ගණන අඩු වේ", "ලෝහවල සක්‍රීයතාව අඩු වේ", "I කාණ්ඩයේ පහළට යත්ම ඉලෙක්ට්‍රෝන ඉවත් කිරීම පහසු වන බැවින් සක්‍රීයතාව වැඩි වේ."),
    q("පරමාණුවකින් ඉලෙක්ට්‍රෝනයක් ඉවත් කොට +1 ආරෝපිත වායුමය අයනයක් සෑදීමට අවශ්‍ය ශක්තිය කුමක්ද?", "පළමු අයනීකරණ ශක්තිය", "විද්‍යුත් සෘණතාව", "ඉලෙක්ට්‍රෝන බන්ධුතාව", "ද්‍රවාංකය", "ඉලෙක්ට්‍රෝනය න්‍යෂ්ටියට තදින් බැඳී ඇති විට අයනීකරණ ශක්තිය වැඩිය."),
    q("ආවර්තිතා වගුවේ 3 වන ආවර්තයේ ඉහළම පළමු අයනීකරණ ශක්තිය ඇති මූලද්‍රව්‍යය කුමක්ද?", "ආගන් (Ar)", "සෝඩියම් (Na)", "ක්ලෝරීන් (Cl)", "සිලිකන් (Si)", "උච්ච වායුවල ස්ථායී අෂ්ටකයෙන් ඉලෙක්ට්‍රෝනයක් ගැලවීම ඉතා අපහසුය."),
    q("සහසංයුජ බන්ධනයක ඉලෙක්ට්‍රෝන යුගල තමා දෙසට ඇද ගැනීමට පරමාණුවක ඇති හැකියාව හඳුන්වන්නේ කෙසේද?", "විද්‍යුත් සෘණතාව (Electronegativity)", "අයනීකරණ ශක්තිය", "සංයුජතාව", "මවුලික ස්කන්ධය", "ෆ්ලුවොරීන් (F) යනු ඉහළම විද්‍යුත් සෘණතාව ඇති මූලද්‍රව්‍යයයි."),
    q("පරමාණු අංක 1 සිට 20 දක්වා මූලද්‍රව්‍ය අතරින් ඉහළම විද්‍යුත් සෘණතාව ඇති මූලද්‍රව්‍යය කුමක්ද?", "ෆ්ලුවොරීන් (F)", "ඔක්සිජන් (O)", "ක්ලෝරීන් (Cl)", "සෝඩියම් (Na)", "ෆ්ලුවොරීන් කුඩා පරමාණුවක් වීමත් කවචයේ 7 ක් තිබීමත් මීට හේතුවයි."),
    q("සිලිකන් (Si) සහ බෝරෝන් (B) යන මූලද්‍රව්‍ය හැඳින්වෙන්නේ කුමන කාණ්ඩය ලෙසද?", "ලෝහාලෝහ / අර්ධ ලෝහ (Metalloids)", "ක්ෂාර ලෝහ", "උච්ච වායු", "හැලජන", "මේවා ලෝහ හා අලෝහ යන දෙකෙහිම අතරමැදි ගුණ (අර්ධ සන්නායක ගුණ) පෙන්වයි."),
    q("සෝඩියම් ක්ලෝරයිඩ් (NaCl) සෑදීමේදී Na පරමාණුව හා Cl පරමාණුව අතර සිදු වන්නේ කුමක්ද?", "Na ඉලෙක්ට්‍රෝනයක් Cl වෙත සම්පූර්ණයෙන්ම පරිත්‍යාග කිරීම", "ඉලෙක්ට්‍රෝන හවුලේ තබා ගැනීම", "ප්‍රෝටෝන හුවමාරු කිරීම", "නියුට්‍රෝන බෙදා ගැනීම", "Na⁺ හා Cl⁻ අයන අතර ප්‍රබල ස්ථිති විද්‍යුත් ආකර්ෂණයෙන් අයනික බන්ධනය සෑදේ."),
    q("ධන අයනයක් සහ සෘණ අයනයක් අතර ඇතිවන ස්ථිති විද්‍යුත් ආකර්ෂණ බලය හඳුන්වන්නේ කුමන බන්ධනයක් ලෙසද?", "අයනික බන්ධනය", "සහසංයුජ බන්ධනය", "හයිඩ්‍රජන් බන්ධනය", "ලෝහක බන්ධනය", "ලෝහ හා අලෝහ අතර බොහෝ විට අයනික බන්ධන සෑදේ."),
    q("මැග්නීසියම් (සංයුජතාව 2) සහ ක්ලෝරීන් (සංයුජතාව 1) සංයෝජනය වී සාදන අයනික සංයෝගයේ රසායනික සූත්‍රය කුමක්ද?", "MgCl₂", "MgCl", "Mg₂Cl", "Mg₂Cl₂", "ආරෝපණ තුලනය කිරීම සඳහා Mg²⁺ එකකට Cl⁻ දෙකක් අවශ්‍ය වේ."),
    q("ඇලුමිනියම් (Al³⁺) සහ ඔක්සයිඩ් (O²⁻) අයන එක්ව සාදන ඇලුමිනියම් ඔක්සයිඩ්වල රසායනික සූත්‍රය කුමක්ද?", "Al₂O₃", "AlO", "Al₃O₂", "AlO₂", "සංයුජතා මාරු කර ලියූ විට Al₂O₃ ලැබේ."),
    q("සෝඩියම් සල්ෆේට් සංයෝගයේ නිවැරදි රසායනික සූත්‍රය කුමක්ද? (SO₄²⁻)", "Na₂SO₄", "NaSO₄", "Na(SO₄)₂", "Na₂S", "Na⁺ අයන දෙකක් SO₄²⁻ අයනයක් සමඟ සම්බන්ධ වේ."),
    q("කැල්සියම් කාබනේට් (Ca²⁺, CO₃²⁻) සංයෝගයේ නිවැරදි රසායනික සූත්‍රය කුමක්ද?", "CaCO₃", "Ca₂CO₃", "Ca(CO₃)₂", "Ca₃CO₂", "දෙකෙහිම සංයුජතාව 2 බැවින් 1:1 අනුපාතයෙන් එක් වේ."),
    q("ඇමෝනියම් ක්ලෝරයිඩ්හි (NH₄⁺, Cl⁻) අඩංගු බන්ධන වර්ග මොනවාද?", "සහසංයුජ සහ අයනික බන්ධන", "අයනික බන්ධන පමණි", "සහසංයුජ බන්ධන පමණි", "ලෝහක බන්ධන", "NH₄⁺ ඇතුළත N-H සහසංයුජ බන්ධන ද NH₄⁺ හා Cl⁻ අතර අයනික බන්ධන ද පවතී."),
    q("අලෝහ පරමාණු දෙකක් ඉලෙක්ට්‍රෝන යුගල හවුලේ බෙදා ගැනීමෙන් සෑදෙන රසායනික බන්ධනය කුමක්ද?", "සහසංයුජ බන්ධනය", "අයනික බන්ධනය", "ලෝහක බන්ධනය", "ගුරුත්වාකර්ෂණ බන්ධනය", "H₂, Cl₂, H₂O සහ CH₄ සහසංයුජ අණු වේ."),
    q("නයිට්‍රජන් අණුවක (N₂) නයිට්‍රජන් පරමාණු දෙක අතර පවතින සහසංයුජ බන්ධනය කෙබඳුද?", "ත්‍රිත්ව සහසංයුජ බන්ධනයක් (N≡N)", "ඒක බන්ධනයක්", "ද්විත්ව බන්ධනයක්", "අයනික බන්ධනයක්", "එක් N පරමාණුවක අවසන් කවචයේ ඉලෙක්ට්‍රෝන 5 ක් ඇති නිසා යුගල 3 ක් හවුලේ තබා ගනී."),
    q("ඔක්සිජන් අණුවක (O₂) පරමාණු දෙක අතර හවුලේ තබාගෙන ඇති මුළු ඉලෙක්ට්‍රෝන සංඛ්‍යාව කීයද?", "4 (බන්ධන යුගල 2)", "2", "6", "8", "ඔක්සිජන් පරමාණු දෙක අතර ද්විත්ව සහසංයුජ බන්ධනයක් (O=O) ඇත."),
    q("මීතේන් (CH₄) අණුවේ කාබන් පරමාණුව වටා පවතින ඒක සහසංයුජ බන්ධන ගණන කීයද?", "4", "2", "3", "6", "කාබන් හි සංයුජතාව 4 කි."),
    q("අයනික සංයෝගවල සාමාන්‍ය භෞතික ගුණයක් නොවන්නේ කුමක්ද?", "වාෂ්පශීලී අඩු ද්‍රවාංක ඇති ද්‍රව වීම", "ඉහළ ද්‍රවාංක හා තාපාංක පැවතීම", "ජලීය ද්‍රාවණ හා විලීන අවස්ථාවේදී විදුලිය සන්නයනය කිරීම", "ස්ඵටිකරූපී ඝන ද්‍රව්‍ය වීම", "අයනික සංයෝග කාමර උෂ්ණත්වයේදී ඝන ස්ඵටික වන අතර ඉහළ ද්‍රවාංක දරයි."),
    q("සහසංයුජ සරල අණුක ද්‍රව්‍ය (උදා: ඉටි, කපුරු) බොහෝ විට පහළ ද්‍රවාංක පෙන්වීමට හේතුව කුමක්ද?", "අණු අතර ඇති අන්තර්-අණුක ආකර්ෂණ බල දුර්වල වීම", "පරමාණු අතර සහසංයුජ බන්ධන දුර්වල වීම", "අයන බහුල වීම", "ඉලෙක්ට්‍රෝන නොමැති වීම", "තාපය සැපයූ විට කැඩී යන්නේ දුර්වල අන්තර් අණුක බලයි."),
    q("කාබන් හි යෝධ සහසංයුජ දැලිස් ව්‍යුහ දෙක අතුරින් විද්‍යුතය සන්නයනය කරන මෘදු බහුරූපියා කවුද?", "මිනිරන් (Graphite)", "දියමන්ති (Diamond)", "සිලිකා", "ක්වාට්ස්", "මිනිරන්වල සෑම කාබන් පරමාණුවකටම නිදහස් ඉලෙක්ට්‍රෝනයක් පවතී."),
    q("ලෝකයේ ස්වභාවිකව හමුවන දැඩිම ඛනිජය වන දියමන්ති අතිශයින්ම දැඩි වීමට හේතුව කුමක්ද?", "සෑම C පරමාණුවක්ම තවත් C 4 කට ප්‍රබල ත්‍රිමාණ සහසංයුජ බන්ධනවලින් බැඳී තිබීම", "එහි අයනික බන්ධන තිබීම", "එහි නිදහස් ඉලෙක්ට්‍රෝන තිබීම", "ලෝහමය බන්ධන තිබීම", "ත්‍රිමාණ චතුස්තලීය දැලිස නිසා ඉතා ඉහළ ද්‍රවාංකයක් හා දැඩි බවක් ඇත."),
    q("ජල අණුව (H₂O) ධ්‍රැවීය (Polar) අණුවක් වීමට හේතුව කුමක්ද?", "O පරමාණුවේ විද්‍යුත් සෘණතාව H ට වඩා බොහෝ වැඩි වීම හා කෝණික හැඩය", "O පරමාණුව ධන ආරෝපිත වීම", "අණුව රේඛීය වීම", "එහි අයනික බන්ධන තිබීම", "O පරමාණුව මත සුළු සෘණ (δ⁻) සහ H මත සුළු ධන (δ⁺) ආරෝපණ ඇතිවේ."),
    q("සාමාන්‍ය ජලයේ අණු අතර පවතින ප්‍රබල විශේෂ අන්තර්-අණුක ආකර්ෂණ බලය කුමක්ද?", "හයිඩ්‍රජන් බන්ධන", "අයනික බන්ධන", "ලෝහක බන්ධන", "විකිරණ බල", "හයිඩ්‍රජන් බන්ධන නිසා ජලයට ඉහළ තාපාංකයක් (100°C) හා ඉහළ පෘෂ්ඨික ආතතියක් ලැබේ."),
    q("4°C දී ජලයේ ඝනත්වය උපරිම වී, අයිස් ජලයේ පාවීමට ප්‍රධාන හේතුව කුමක්ද?", "හයිඩ්‍රජන් බන්ධන නිසා අයිස්වල විවෘත හිස් අවකාශ සහිත ස්ඵටික දැලිසක් සෑදීම", "අයිස් ජලයට වඩා බර වීම", "අයිස්වල ඔක්සිජන් නොමැති වීම", "අයිස්වල වායු බුබුළු නැති වීම", "මෙම ගුණය ශීත රටවල ජලජ ජීවීන් අයිස් යට නොනැසී සිටීමට උපකාරී වේ."),
    q("ඝන NaCl ස්ඵටික විදුලිය සන්නයනය නොකරන නමුත් NaCl ජලීය ද්‍රාවණය විදුලිය සන්නයනය කරන්නේ ඇයි?", "ජලීය ද්‍රාවණයේ චලනය විය හැකි නිදහස් Na⁺ සහ Cl⁻ අයන පැවතීම", "ජලය පමණක් විදුලිය සන්නයනය කිරීම", "සෝඩියම් ලෝහය දිය වීම", "ඉලෙක්ට්‍රෝන ද්‍රාවණය හරහා පිහිනීම", "ඝන තත්ත්වයේදී අයන ස්ථානගතව සිරවී ඇත."),
    q("කිසියම් ද්‍රව්‍යයක් ද්‍රවයක සම්පූර්ණයෙන් දිය වී සෑදෙන සමජාතීය මිශ්‍රණය හඳුන්වන්නේ කුමන නමින්ද?", "ද්‍රාවණයක් (Solution)", "අවලම්බනයක්", "පයසක්", "කලිලයක්", "ද්‍රාව්‍යය හා ද්‍රාවකය එක්ව සමජාතීය ද්‍රාවණයක් සාදයි."),
    q("තෙල් සහ ජලය එකට මිශ්‍ර නොවී වෙන් වී පැවතීමට ප්‍රධාන රසායනික හේතුව කුමක්ද?", "ජලය ධ්‍රැවීය වන අතර තෙල් නිර්ධ්‍රැවීය වීම", "තෙල් ඝන වීම", "ජලය ආම්ලික වීම", "දෙකම ලෝහ වීම", "'සමාන ද්‍රාව්‍ය සමාන ද්‍රාවකවල දියවේ' (Like dissolves like) යන මූලධර්මය බලපායි."),
    q("කිසියම් නිශ්චිත උෂ්ණත්වයකදී ද්‍රාවකයක තවදුරටත් ද්‍රාව්‍යය දිය කළ නොහැකි උපරිම අවස්ථාවේ ඇති ද්‍රාවණය කුමක්ද?", "සංතෘප්ත ද්‍රාවණය", "අසංතෘප්ත ද්‍රාවණය", "තනුක ද්‍රාවණය", "අවලම්බනය", "උෂ්ණත්වය වැඩි කළ විට බොහෝ ඝන ද්‍රව්‍යවල ද්‍රාව්‍යතාව ඉහළ යයි."),
    q("සෝඩා වතුර වැනි ජලයේ දිය කර ඇති කාබන් ඩයොක්සයිඩ් වායුවේ ද්‍රාව්‍යතාව වැඩි කිරීම සඳහා කර්මාන්තශාලාවල කරන්නේ කුමක්ද?", "උෂ්ණත්වය අඩු කර පීඩනය වැඩි කිරීම", "උෂ්ණත්වය ඉහළ දැමීම", "ලුණු දැමීම", "විවෘතව තැබීම", "වායුවල ද්‍රාව්‍යතාව අඩු උෂ්ණත්වයේදී හා ඉහළ පීඩනයේදී වැඩිය."),
    q("ද්‍රාවණ 1 dm³ (1 L) ක දිය වී ඇති ද්‍රාව්‍ය මවුල සංඛ්‍යාව හඳුන්වන්නේ කුමන ඒකකයෙන්ද?", "මවුලිකතාව / සාන්ද්‍රණය (mol dm⁻³)", "ඝනත්වය", "ප්‍රතිශතය", "ද්‍රාව්‍යතාව", "සාන්ද්‍රණය C = n / V ලෙස ගණනය කෙරේ."),
    q("ජලය 500 cm³ ක NaOH (M = 40 g mol⁻¹) ග්‍රෑම් 20 ක් දිය කර සාදාගත් ද්‍රාවණයේ සාන්ද්‍රණය කීයද?", "1.0 mol dm⁻³", "0.5 mol dm⁻³", "2.0 mol dm⁻³", "4.0 mol dm⁻³", "n = 20 / 40 = 0.5 mol; V = 0.5 dm³ -> C = 0.5 / 0.5 = 1.0 mol dm⁻³."),
    q("1.0 mol dm⁻³ NaCl ද්‍රාවණයකින් 250 cm³ ක් සෑදීමට අවශ්‍ය NaCl (M = 58.5 g mol⁻¹) ස්කන්ධය කොපමණද?", "14.625 g", "58.5 g", "29.25 g", "117 g", "n = C × V = 1.0 × 0.25 = 0.25 mol; m = 0.25 × 58.5 = 14.625 g."),
    q("ලුණු සහ ජලය මිශ්‍රණයකින් පිරිසිදු ආස්‍රැත ජලය වෙන් කර ගැනීමට වඩාත් සුදුසු භෞතික වෙන් කිරීමේ ක්‍රමය කුමක්ද?", "සරල ආසවනය (Simple distillation)", "පෙරීම", "චුම්භක වෙන් කිරීම", "අවසාදනය", "ජලය වාෂ්ප කර ඝනීභවනය කිරීමෙන් පිරිසිදු ජලය ලබා ගනී."),
    q("බොරතෙල්වලින් පෙට්‍රල්, භූමිතෙල් හා ඩීසල් වැනි තාපාංක ආසන්න සංරචක වෙන් කර ගැනීමට යොදා ගන්නා ක්‍රමය කුමක්ද?", "භාගික ආසවනය (Fractional distillation)", "ස්ඵටිකීකරණය", "පෙරීම", "හුමාල ආසවනය", "භාගික කුළුණක තාපාංක වෙනස මත භාග වෙන් කර ගනී."),
    q("සමුද්‍ර ජලයෙන් පොදු ලුණු (NaCl) වෙන් කර ගැනීමේදී ලුණු ලේවායන්හි යොදා ගන්නා ක්‍රියාවලිය කුමක්ද?", "වාෂ්පීකරණය හා ස්ඵටිකීකරණය", "වර්ණලේඛ ශිල්පය", "සරල පෙරීම", "විද්‍යුත් විච්ඡේදනය", "හිරු එළියෙන් හා සුළඟින් ජලය වාෂ්ප වී ලුණු ස්ඵටික ඉතිරි වේ."),
    q("විලියක ඇති වර්ණක සංරචක කිහිපයක් හෝ ඖෂධ කුඩා ප්‍රමාණයක් වෙන් කර හඳුනා ගැනීමට යොදා ගන්නා ශිල්පීය ක්‍රමය කුමක්ද?", "වර්ණලේඛ ශිල්පය (Chromatography)", "භාගික ආසවනය", "නිස්සාරණය", "හුමාල ආසවනය", "ද්‍රාවකයේ ද්‍රාව්‍යතාව හා කඩදාසියට ඇති ආකර්ෂණය අනුව වර්ණක වෙනස් උසකට ගමන් කරයි."),
    q("කුරුඳු කොළ හෝ කරාබුනැටි වලින් සගන්ධ තෙල් (Essential oils) වෙන් කර ගැනීමේදී භාවිත කරන ක්‍රමය කුමක්ද?", "හුමාල ආසවනය (Steam distillation)", "සරල පෙරීම", "ස්ඵටිකීකරණය", "අපකේන්ද්‍රණය", "ඉහළ තාපාංක ඇති තෙල් හුමාලය සමඟ පහළ උෂ්ණත්වයකදී වාෂ්පීභවනය වේ."),
    q("ජලය හා පොල් තෙල් වැනි මිශ්‍ර නොවන ද්‍රව දෙකක් පහසුවෙන් වෙන් කර ගැනීමට රසායනාගාරයේදී භාවිත කරන උපකරණය කුමක්ද?", "වෙන් කරන පුනීලය (Separating funnel)", "බියුරෙට්ටුව", "පිපෙට්ටුව", "ලීබිග් කන්ඩෙන්සරය", "ඝනත්වය වැඩි ජලය පහළ ස්තරයේ රැඳෙන බැවින් කරාමයෙන් ඉවත් කළ හැක."),
    q("රතු-රෝස පැහැති කොපර්(II) සල්ෆේට් වෙනුවට නිල් CuSO₄ ස්ඵටික සාදන ජලීය ස්ඵටිකීකරණයේදී CuSO₄ ස්ඵටිකවල අඩංගු 'ස්ඵටික ජල' අණු ගණන කීයද?", "5 (CuSO₄·5H₂O)", "2", "7", "10", "ජලීය කොපර් සල්ෆේට් පෙන්ටාහයිඩ්‍රේට් නිල් පැහැති වන අතර නිර්ජලීය CuSO₄ සුදු පැහැතිය."),
    q("මූලද්‍රව්‍යයක් වන බෙරිලියම් (Z=4) සහ මැග්නීසියම් (Z=12) සමාන රසායනික ගුණ පෙන්වීමට හේතුව කුමක්ද?", "දෙකෙහිම අවසන් කවචයේ ඉලෙක්ට්‍රෝන 2 බැගින් පැවතීම", "ස්කන්ධ ක්‍රමාංක සමාන වීම", "කවච ගණන සමාන වීම", "නියුට්‍රෝන ගණන සමාන වීම", "එකම කාණ්ඩයේ මූලද්‍රව්‍යවල සංයුජතා ඉලෙක්ට්‍රෝන ගණන සමානය."),
    q("ලෝහක ස්ඵටිකයක් තුළ පරමාණු එකට බැඳ තබා ගන්නා බන්ධන ස්වභාවය කෙබඳුද?", "ධන ලෝහ අයන සහ නිදහස්ව සැරිසරන ඉලෙක්ට්‍රෝන වලාව අතර ආකර්ෂණය", "සෘණ අයන අතර විකර්ෂණය", "සහසංයුජ යුගල පමණි", "හයිඩ්‍රජන් බන්ධන", "නිදහස් ඉලෙක්ට්‍රෝන වලාව ලෝහවල විද්‍යුත් හා තාප සන්නායකතාවට හේතු වේ."),
    q("ලෝහ තලා තහඩු බවට පත් කිරීමේ හැකියාව (ආහන්‍යතාව) හා කම්බි බවට ඇදීමේ හැකියාව (තන්‍යතාව) පවතින්නේ ඇයි?", "බලයක් යෙදූ විට ලෝහ බන්ධන නොකැඩී ලෝහ අයන ස්තර ලිස්සා යා හැකි බැවින්", "ලෝහ අණු ද්‍රව වීම නිසා", "ලෝහවල අයනික බන්ධන තිබීම නිසා", "නියුට්‍රෝන චලනය නිසා", "මෙම ගුණය නිසා තඹ හා ඇලුමිනියම් කම්බි හා තහඩු සෑදිය හැක."),
    q("සංයුජතාව 1 වන මූලද්‍රව්‍ය X (ලෝහය) සහ සංයුජතාව 2 වන මූලද්‍රව්‍ය Y (අලෝහය) සාදන සංයෝගයේ සූත්‍රය කුමක්ද?", "X₂Y", "XY₂", "XY", "X₂Y₃", "X⁺ අයන දෙකක් Y²⁻ අයනයක් සමඟ සම්බන්ධ වේ."),
    q("වායුගෝලයේ ඇති ආගන් (Ar) වායුව ඒකපරමාණුක අණු ලෙස පවතින්නේ ඇයි?", "එහි අවසන් කවචය ඉලෙක්ට්‍රෝන 8 කින් සම්පූර්ණ වී ස්ථායී බැවින්", "එය ඉතා බර නිසා", "එහි ප්‍රෝටෝන නැති නිසා", "එය සෑම විටම ද්‍රවයක් නිසා", "ආගන් වෙනත් පරමාණු සමඟ ඉලෙක්ට්‍රෝන බෙදා ගැනීමට හෝ හුවමාරු කිරීමට අවශ්‍ය නොවේ."),
    q("සල්ෆර් පරමාණුවක (Z = 16) ඉලෙක්ට්‍රෝන වින්‍යාසය අනුව එය ස්ථායී වීමට සාමාන්‍යයෙන් සාදන අයනය කුමක්ද?", "S²⁻", "S²⁺", "S⁶⁺", "S⁻", "අවසන් කවචයේ ඉලෙක්ට්‍රෝන 6 ක් ඇති බැවින් ඉලෙක්ට්‍රෝන 2 ක් ලබා ගෙන අෂ්ටකය සම්පූර්ණ කරයි."),
    q("ඇලුමිනියම් පරමාණුව (2, 8, 3) අයනික සංයෝග සෑදීමේදී සාදන අයනයේ ඉලෙක්ට්‍රෝන වින්‍යාසය කුමක්ද?", "2, 8", "2, 8, 3", "2, 8, 8", "2, 8, 6", "Al පරමාණුව අවසන් කවචයේ ඉලෙක්ට්‍රෝන 3 ඉවත් කර Al³⁺ (2, 8) අයනය සාදයි."),
    q("පොටෑසියම් ක්ලෝරයිඩ් (KCl) ජලීය ද්‍රාවණයක අඩංගු වන්නේ කුමන අංශුද?", "K⁺ අයන, Cl⁻ අයන සහ H₂O අණු", "K පරමාණු සහ Cl₂ අණු", "KCl අණු පමණි", "K⁺ සහ H₂ වායුව", "ජලයේදී අයනික ස්ඵටිකය නිදහස් ජලීය අයන බවට විඝටනය වේ."),
    q("කිසියම් ද්‍රාවණයක ස්කන්ධ ප්‍රතිශතය (w/w %) 10% ක් ලෙස දක්වා ඇත්නම්, ද්‍රාවණය 200 g ක අඩංගු ද්‍රාව්‍ය ස්කන්ධය කීයද?", "20 g", "10 g", "40 g", "2 g", "200 × (10 / 100) = 20 g."),
    q("ජලය 90 g ක සීනි 10 g ක් දිය කර සාදාගත් සීනි ද්‍රාවණයේ ස්කන්ධ ප්‍රතිශතය කීයද?", "10%", "11.1%", "9%", "20%", "මුළු ද්‍රාවණ ස්කන්ධය = 90 + 10 = 100 g; ප්‍රතිශතය = (10 / 100) × 100% = 10%."),
    q("පරමාණුක ක්‍රමාංකය 6 වන කාබන් පරමාණුවේ සංයුජතා කවචයේ ඇති ඉලෙක්ට්‍රෝන ගණන කීයද?", "4", "2", "6", "8", "ඉලෙක්ට්‍රෝන වින්‍යාසය 2, 4 වේ."),
    q("සෝඩියම් (Na), පොටෑසියම් (K) වැනි ක්ෂාර ලෝහ භූමිතෙල් තුළ ගිල්වා ගබඩා කරන්නේ ඇයි?", "වාතයේ ඇති ඔක්සිජන් හා ජල වාෂ්ප සමඟ ඉක්මනින් ප්‍රතික්‍රියා කිරීම වැළැක්වීමට", "ලෝහ දිය වීම වැළැක්වීමට", "ලෝහවල ඝනත්වය වැඩි කිරීමට", "ලෝහ වර්ණවත් කිරීමට", "භූමිතෙල් නිර්ධ්‍රැවීය හයිඩ්‍රොකාබනයක් බැවින් ලෝහ සමඟ ප්‍රතික්‍රියා නොකරයි."),
    q("පොටෑසියම් පර්මැංගනේට් (KMnO₄) ස්ඵටිකයක් ජලය බීකරයකට දැමූ විට දම් පැහැය ක්‍රමයෙන් මුළු ජලය පුරාම පැතිර යන්නේ කුමන සංසිද්ධිය නිසාද?", "විසරණය (Diffusion)", "ආස්‍රැතිය", "උත්ස්වේදනය", "අවසාදනය", "ද්‍රාව්‍ය අංශු වැඩි සාන්ද්‍රණයේ සිට අඩු සාන්ද්‍රණය වෙත අහඹු ලෙස ගමන් කරයි."),
    q("බොහෝ විට සුදු පැහැති ක්ෂුද්‍ර ස්ඵටික සාදන අයනික ලවණවලට වෙනස්ව, නිල් හෝ කොළ වැනි වර්ණවත් සංයෝග සාදන මූලද්‍රව්‍ය කාණ්ඩය කුමක්ද?", "සංක්‍රාන්ති ලෝහ (උදා: Cu, Fe, Mn)", "ක්ෂාර ලෝහ", "උච්ච වායු", "ක්ෂාරීය පාංශු ලෝහ", "සංක්‍රාන්ති ලෝහ විචල්‍ය සංයුජතා සහ උත්ප්‍රේරක ගුණ ද පෙන්වයි."),
    q("කිසියම් ද්‍රවයක හා වායුවක පවතින අංශුවල චලනය පිළිබඳව රොබට් බ්‍රවුන් නිරීක්ෂණය කළ අහඹු ගමන හඳුන්වන්නේ කෙසේද?", "බ්‍රවුනීය චලිතය", "රේඛීය චලිතය", "වෘත්තාකාර චලිතය", "සරල අනුවර්තී චලිතය", "ද්‍රාවක අණු විසින් අවලම්බිත අංශු මත ගැටීම නිසා මෙම අහඹු චලනය ඇති වේ."),
    q("ඝන ද්‍රව්‍යයක් රත් කළ විට ද්‍රව අවස්ථාවට පත් නොවී කෙළින්ම වායු අවස්ථාවට පත් වීම කුමක්ද?", "ඌර්ධ්වපාතනය (Sublimation)", "වාෂ්පීභවනය", "ඝනීභවනය", "විලයනය", "අයඩීන්, කපුරු හා නැප්තලීන් ඌර්ධ්වපාතනය වන ද්‍රව්‍ය වේ."),
    q("අපිරිසිදු අයඩීන් ස්ඵටිකවලින් වැලි වෙන් කර ගැනීමට වඩාත් සුදුසු ක්‍රමය කුමක්ද?", "ඌර්ධ්වපාතනය", "ආසවනය", "චුම්භක වෙන් කිරීම", "අපකේන්ද්‍රණය", "රත් කළ විට අයඩීන් වාෂ්ප වී සිසිල් පෘෂ්ඨයේ නැවත ඝන වන අතර වැලි ඉතිරි වේ."),
    q("බෙන්සීන් හෝ පෙට්‍රල් වැනි නිර්ධ්‍රැවීය ද්‍රාවකයක පහසුවෙන් දිය වන ද්‍රව්‍යයක් වන්නේ කුමක්ද?", "ග්‍රීස් හා ඉටි", "සෝඩියම් ක්ලෝරයිඩ්", "සීනි", "කොපර් සල්ෆේට්", "නිර්ධ්‍රැවීය ද්‍රාව්‍ය නිර්ධ්‍රැවීය ද්‍රාවකවල හොඳින් දියවේ."),
    q("උෂ්ණත්වය ඉහළ යාමත් සමඟ බොහෝ ඝන ද්‍රව්‍යවල (උදා: KNO₃) ජලයේ ද්‍රාව්‍යතාවට සිදුවන්නේ කුමක්ද?", "ද්‍රාව්‍යතාව ශීඝ්‍රයෙන් වැඩි වේ", "ද්‍රාව්‍යතාව ශුන්‍ය වේ", "ද්‍රාව්‍යතාව සෑම විටම අඩු වේ", "කිසිසේත් වෙනස් නොවේ", "උණුසුම් සංතෘප්ත KNO₃ ද්‍රාවණයක් සිසිල් කළ විට පිරිසිදු ස්ඵටික නැවත තැන්පත් වේ."),
    q("හයිඩ්‍රජන් ක්ලෝරයිඩ් (HCl) අණුවේ පවතින්නේ කුමන ආකාරයේ සහසංයුජ බන්ධනයක්ද?", "ධ්‍රැවීය සහසංයුජ බන්ධනයක්", "නිර්ධ්‍රැවීය සහසංයුජ බන්ධනයක්", "ලෝහක බන්ධනයක්", "ද්විත්ව බන්ධනයක්", "Cl හි විද්‍යුත් සෘණතාව H ට වඩා වැඩි බැවින් බන්ධන ඉලෙක්ට්‍රෝන Cl දෙසට ඇදේ."),
    q("කාබන් ඩයොක්සයිඩ් (O=C=O) අණුවේ කාබන් පරමාණුව වටා පවතින බන්ධන ව්‍යුහය කුමක්ද?", "ද්විත්ව සහසංයුජ බන්ධන දෙකක් (රේඛීය අණුවකි)", "ඒක බන්ධන හතරක්", "ත්‍රිත්ව බන්ධනයක්", "අයනික බන්ධනයක්", "O=C=O රේඛීය හා සමමිතික බැවින් සමස්ත අණුව නිර්ධ්‍රැවීය වේ."),
    q("වීදුරුවක ඇති ශුද්ධ ජලයේ විද්‍යුත් සන්නායකතාව ඉතාම අල්ප වීමට හේතුව කුමක්ද?", "ජලය ප්‍රධාන වශයෙන් සහසංයුජ අණුවලින් සමන්විත වී නිදහස් අයන ඉතා ස්වල්පයක් තිබීම", "ජලයේ හයිඩ්‍රජන් නොමැති වීම", "ජලය අයනික ද්‍රව්‍යයක් වීම", "ජල අණු චලනය නොවීම", "ජලයට ලුණු හෝ අම්ල බිංදුවක් එක් කළ විගස සන්නායකතාව ඉහළ යයි."),
    q("සෝඩියම් හයිඩ්‍රොක්සයිඩ් (NaOH) 1 mol ක් ජලයේ දිය කර 2 dm³ ද්‍රාවණයක් සෑදූ විට සාන්ද්‍රණය කීයද?", "0.5 mol dm⁻³", "2.0 mol dm⁻³", "1.0 mol dm⁻³", "4.0 mol dm⁻³", "C = n / V = 1 / 2 = 0.5 mol dm⁻³."),
    q("මූලද්‍රව්‍ය X හි පරමාණුක ක්‍රමාංකය 9 කි. එහි පරමාණුවක ඇති කවච ගණන හා සංයුජතාව කීයද?", "කවච 2, සංයුජතාව 1", "කවච 2, සංයුජතාව 7", "කවච 3, සංයුජතාව 1", "කවච 1, සංයුජතාව 2", "Z = 9 -> වින්‍යාසය 2, 7. අෂ්ටකය සඳහා ඉලෙක්ට්‍රෝන 1 ක් ලබා ගන්නා බැවින් සංයුජතාව 1 කි."),
    q("පහත දැක්වෙන මූලද්‍රව්‍ය අතුරින් වඩාත්ම ක්‍රියාශීලී අලෝහය (හැලජනය) කුමක්ද?", "ෆ්ලුවොරීන් (F)", "ක්ලෝරීන් (Cl)", "බ්‍රෝමීන් (Br)", "අයඩීන් (I)", "හැලජන කාණ්ඩයේ ඉහළට යත්ම ඉලෙක්ට්‍රෝනයක් ආකර්ෂණය කර ගැනීමේ හැකියාව වැඩි වේ."),
    q("දී ඇති උෂ්ණත්වයකදී කිසියම් ද්‍රාවකයක ද්‍රාව්‍යය ක්‍රමයෙන් තවත් දිය කළ හැකි ද්‍රාවණයක් හඳුන්වන්නේ කෙසේද?", "අසංතෘප්ත ද්‍රාවණය", "සංතෘප්ත ද්‍රාවණය", "අතිසංතෘප්ත ද්‍රාවණය", "අවලම්බනය", "එහි දියවී ඇති ප්‍රමාණය ද්‍රාව්‍යතාවට වඩා අඩුය."),
    q("ඇමෝනියා (NH₃) අණුවේ නයිට්‍රජන් පරමාණුව සතු බන්ධනවලට සහභාගී නොවූ 'එකලා ඉලෙක්ට්‍රෝන යුගල' (Lone pairs) ගණන කීයද?", "1", "2", "3", "4", "N සතු සංයුජතා ඉලෙක්ට්‍රෝන 5 න් 3 ක් H සමඟ බන්ධන සාදන අතර යුගල 1 ක් ඉතිරි වේ."),
    q("ජලය හා ඊතයිල් මධ්‍යසාරය (එතනෝල්) මිශ්‍රණයකින් එතනෝල් වෙන් කර ගැනීම සඳහා වඩාත්ම සුදුසු ක්‍රමය කුමක්ද?", "භාගික ආසවනය", "පෙරීම", "වෙන් කරන පුනීලය", "අවසාදනය", "එතනෝල් (78°C) හා ජලය (100°C) පූර්ණ ලෙස මිශ්‍ර වන ද්‍රව දෙකකි."),
    q("සෝඩියම් කාබනේට් (Na₂CO₃) අණු ඒකකයක අඩංගු මුළු පරමාණු සංඛ්‍යාව කීයද?", "6", "3", "5", "4", "Na 2 + C 1 + O 3 = පරමාණු 6 කි."),
    q("මූලද්‍රව්‍යයක රසායනික සංකේතය වටා දක්වන අංක අතුරින් '²⁷₁₃Al' හි 27 යන්නෙන් දැක්වෙන්නේ කුමක්ද?", "ස්කන්ධ ක්‍රමාංකය (නියුක්ලියෝන සංඛ්‍යාව)", "පරමාණුක ක්‍රමාංකය", "නියුට්‍රෝන ගණන", "සංයුජතාව", "ඉහළින් ස්කන්ධ ක්‍රමාංකය (27) ද පහළින් පරමාණුක ක්‍රමාංකය (13) ද දක්වයි."),
    q("අයනීකරණ ශක්තිය සම්බන්ධයෙන් පහත කුමන ප්‍රකාශය නිවැරදිද?", "ලෝහ පරමාණුවල අයනීකරණ ශක්තිය සාපේක්ෂව අඩුය", "උච්ච වායුවල අයනීකරණ ශක්තිය ශුන්‍ය වේ", "හැලජනවල අයනීකරණ ශක්තිය ක්ෂාර ලෝහවලට වඩා අඩුය", "ලෝහ පහසුවෙන් සෘණ අයන සාදයි", "ලෝහ පහසුවෙන් ඉලෙක්ට්‍රෝන පිට කර කැටායන සාදයි."),
    q("මැග්නීසියම් ක්ලෝරයිඩ් (MgCl₂) ද්‍රවීභවනය කර විලීන අවස්ථාවට ගෙන ආ විට එහි ඇති අයන මොනවාද?", "Mg²⁺ සහ Cl⁻", "Mg⁺ සහ Cl²⁻", "Mg²⁻ සහ Cl⁺", "Mg සහ Cl₂", "විලීන MgCl₂ හි නිදහස් අයන පවතින බැවින් විද්‍යුත් විච්ඡේදනය කළ හැක."),
    q("වීදුරු පාත්‍රයක ජලය සමඟ මිශ්‍ර කළ හුණු කුඩු ටික වේලාවකින් පතුලේ තැන්පත් වීම කුමන මිශ්‍රණ ආකාරයට උදාහරණයක්ද?", "අවලම්බනයක් (Suspension - විෂමජාතීය මිශ්‍රණය)", "සැබෑ ද්‍රාවණයක්", "සමජාතීය මිශ්‍රණයක්", "මිශ්‍ර ලෝහයක්", "අවලම්බනයක අංශු ප්‍රමාණයෙන් විශාල බැවින් පෙරීමෙන් වෙන් කළ හැක."),
    q("මිනිරන් හි කාබන් ස්තර එකිනෙක මත පහසුවෙන් ලිස්සා යාම නිසා එය කුමන කාර්යයක් සඳහා යොදා ගනීද?", "වියළි ලිහිසිකාරකයක් හා පැන්සල් කූරු සෑදීමට", "වීදුරු කැපීමට", "ලෝහ කැපීමට", "ප්‍රතිදේහ සෑදීමට", "මිනිරන් ස්තර අතර ඇත්තේ දුර්වල අන්තර් ස්තර ආකර්ෂණ බල වේ."),
    q("කිසියම් ද්‍රාවණයක ඝනත්වය හෝ සාන්ද්‍රණය වෙනස් නොකර තනුක කිරීමේදී (ජලය එක් කිරීමේදී) නොවෙනස්ව පවතින රාශිය කුමක්ද?", "ද්‍රාවණයේ ඇති ද්‍රාව්‍ය මවුල සංඛ්‍යාව (n)", "සාන්ද්‍රණය (C)", "මුළු පරිමාව (V)", "ද්‍රාව්‍යතාව", "තනුක කිරීමේ සූත්‍රය C₁V₁ = C₂V₂ මීට පදනම් වේ.")
  )
}
